def batches(values, size):
    for offset in range(0, len(values), size):
        yield values[offset:offset + size]

function debounce(callback: () => void, delay: number) {
    let timer: ReturnType<typeof setTimeout>;
    return () => { clearTimeout(timer); timer = setTimeout(callback, delay); };
}

public async Task Copy(Stream input, Stream output, CancellationToken stop) {
    byte[] buffer = new byte[4096];
    int count;
    while ((count = await input.ReadAsync(buffer, stop)) != 0) {
        stop.ThrowIfCancellationRequested();
        await output.WriteAsync(buffer.AsMemory(0, count), stop);
    }
}

